const URL='https://fgomaujsdblpzxhnnqrg.supabase.co/rest/v1/';
const KEY='sb_publishable_JOUqLZDnfGu_yCa6k6FVDQ_AYwpr72i';
const $=id=>document.getElementById(id);
const APP_VERSION='1.0.1';
let items=[],selected=null,loadVersion=0,dialogMode='add';
function todayKey(now=new Date()){const parts=new Intl.DateTimeFormat('en-US',{timeZone:'America/Los_Angeles',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(now);const part=type=>parts.find(p=>p.type===type).value;return `${part('year')}-${part('month')}-${part('day')}`}
function scrollToToday(){const wrap=$('grid-wrap');const row=document.querySelector('tr.today');wrap.scrollTop=0;if(row){const header=wrap.querySelector('thead');wrap.scrollTop=Math.max(0,row.getBoundingClientRect().top-wrap.getBoundingClientRect().top-header.getBoundingClientRect().height)}}
const pending=new Map();let saving=false,saveTimer;
async function api(path,method='GET',body){const response=await fetch(URL+path,{method,headers:{apikey:KEY,'Content-Type':'application/json',Prefer:'return=representation,resolution=merge-duplicates'},body:body===undefined?undefined:JSON.stringify(body)});if(!response.ok){let error;try{error=await response.json()}catch{}throw new Error(error?.message||`Connection error (${response.status})`)}return response.status===204?null:response.json()}
function status(message,error=false){$('status').textContent=`v${APP_VERSION} · ${message}`;$('status').classList.toggle('error',error)}
function sortItems(){items.sort((a,b)=>a.name.localeCompare(b.name,'en',{sensitivity:'base'}))}
function renderItems(){sortItems();const value=selected;$('items').replaceChildren(...items.map(item=>{const option=document.createElement('option');option.value=item.id;option.textContent=item.name;return option}));$('items').value=value||'';$('edit').disabled=$('delete').disabled=!selected}
async function refresh(){try{items=await api('pm01_items?select=*&order=created_at.asc');sortItems();let remembered;try{remembered=localStorage.getItem('pm01.selectedItem')}catch{}selected=items.find(item=>item.id===remembered)?.id||items[0]?.id||null;renderItems();if(selected)await choose();else status('Connected · All changes saved')}catch(error){status(error.message+' · Click to retry',true)}}
function buildGrid(entries,readOnly=false){const values=new Map(entries.map(e=>[e.entry_date,e.content]));const fragment=document.createDocumentFragment();const today=todayKey();for(let date=new Date(Date.UTC(2026,9,1));date<=new Date(Date.UTC(2027,5,30));date.setUTCDate(date.getUTCDate()+1)){const iso=date.toISOString().slice(0,10);const label=iso.slice(5)+' '+['Sun','Mon','Tue','Wed','Thu','Fri','Sat'][date.getUTCDay()];const row=document.createElement('tr');if(iso===today){row.className='today';row.setAttribute('aria-current','date')}const day=document.createElement('td');day.className='date';day.textContent=label;const cell=document.createElement('td');const input=document.createElement('textarea');input.rows=1;input.readOnly=readOnly;input.dataset.date=iso;input.value=values.get(iso)||'';input.setAttribute('aria-label',label+' information');const itemId=selected;input.addEventListener('input',()=>queue(itemId,iso,input.value));input.addEventListener('blur',flush);input.addEventListener('input',()=>{input.style.height='auto';input.style.height=input.scrollHeight+'px'});input.style.height=Math.max(37,(input.value.split('\n').length)*21+16)+'px';cell.append(input);row.append(day,cell);fragment.append(row);if(date.getUTCDay()===0){const gap=document.createElement('tr');gap.className='spacer';gap.setAttribute('aria-hidden','true');const td=document.createElement('td');td.colSpan=2;gap.append(td);fragment.append(gap)}}$('grid').replaceChildren(fragment)}
async function choose(){dismissNotes();selected=$('items').value||null;try{if(selected)localStorage.setItem('pm01.selectedItem',selected);else localStorage.removeItem('pm01.selectedItem')}catch{}$('edit').disabled=$('delete').disabled=!selected;const version=++loadVersion;$('grid-wrap').hidden=true;$('empty').hidden=!!selected;if(!selected)return;const item=items.find(i=>i.id===selected);$('title').textContent=item.name;$('description').textContent='October 1, 2026 – June 30, 2027 · Type in any row to add information';status('Loading…');try{const entries=await api('pm01_entries?select=*&item_id=eq.'+selected);if(version!==loadVersion)return;for(const entry of pending.values())if(entry.item_id===selected){const old=entries.find(e=>e.entry_date===entry.entry_date);if(old)old.content=entry.content;else entries.push(entry)}buildGrid(entries);$('grid-wrap').hidden=false;scrollToToday();status((pending.size||notesPending.size)?'Unsaved changes…':'All changes saved')}catch(error){if(version===loadVersion)status(error.message+' · Click to retry',true)}}
function queue(item_id,entry_date,content){pending.set(item_id+':'+entry_date,{item_id,entry_date,content});status('Unsaved changes…');clearTimeout(saveTimer);saveTimer=setTimeout(flush,500)}
async function flush(){clearTimeout(saveTimer);if(saving||(!pending.size&&!notesPending.size))return;saving=true;const batch=[...pending.entries()];status('Saving…');try{if(batch.length)await api('pm01_entries?on_conflict=item_id,entry_date','POST',batch.map(([,entry])=>entry));await saveNotes();for(const [key,entry]of batch)if(pending.get(key)===entry)pending.delete(key);status((pending.size||notesPending.size)?'Saving…':'All changes saved')}catch(error){status('Save failed: '+error.message+' · Click to retry',true);if(notesPending.size)noteStatus('Save failed · Click Retry save',true)}finally{saving=false;if((pending.size||notesPending.size)&&!$('status').classList.contains('error'))saveTimer=setTimeout(flush,100)}}
function openDialog(mode){dialogMode=mode;$('dialog-title').textContent=mode==='add'?'Add item':'Edit item';$('name').value=mode==='edit'?items.find(i=>i.id===selected).name:'';$('dialog-error').textContent='';$('dialog').showModal();$('name').focus()}
$('add').onclick=$('first-add').onclick=()=>openDialog('add');$('edit').onclick=()=>openDialog('edit');$('cancel').onclick=()=>$('dialog').close();
$('item-form').onsubmit=async event=>{event.preventDefault();const name=$('name').value.trim();if(!name){$('dialog-error').textContent='Enter an item name.';return}$('confirm').disabled=true;try{if(dialogMode==='add'){const [item]=await api('pm01_items','POST',{name});items.push(item);selected=item.id}else{await api('pm01_items?id=eq.'+selected,'PATCH',{name});items.find(i=>i.id===selected).name=name}renderItems();$('dialog').close();await choose()}catch(error){$('dialog-error').textContent=error.message}finally{$('confirm').disabled=false}};
$('delete').onclick=async()=>{const item=items.find(i=>i.id===selected);if(!item||!confirm(`Delete “${item.name}” and all its daily information?`))return;$('delete').disabled=true;try{await flush();if(pending.size||notesPending.size||saving)throw new Error('Wait for notes to save before deleting.');await api('pm01_items?id=eq.'+item.id,'DELETE');items=items.filter(i=>i.id!==item.id);selected=null;++loadVersion;dismissNotes();renderItems();$('grid-wrap').hidden=true;$('empty').hidden=false;$('title').textContent='Your daily plan';$('description').textContent='Choose an item on the left, or add a new item.';status('Item deleted')}catch(error){status(error.message,true)}finally{renderItems()}};
$('items').addEventListener('change',choose);
$('items').addEventListener('click',event=>{if(event.detail===1)choose()});
$('status').onclick=()=>{if(pending.size||notesPending.size)flush();else if(selected)choose();else refresh()};
window.addEventListener('beforeunload',event=>{if(pending.size||notesPending.size||saving){event.preventDefault();event.returnValue=''}});document.addEventListener('visibilitychange',()=>{if(document.hidden)flush()});window.addEventListener('online',()=>(pending.size||notesPending.size)?flush():refresh());
// Persist rich item notes separately from the daily grid.
const notesPending=new Map();let noteItem=null,noteVersion=0;
const notesPane=document.createElement('section');notesPane.id='notes-pane';notesPane.hidden=true;
notesPane.innerHTML='<div class="notes-heading"><h3 id="notes-title">Item notes</h3><button type="button" id="notes-close" aria-label="Close notes">Close</button></div><div id="notes-toolbar" role="toolbar" aria-label="Text formatting"><button type="button" data-command="dateStamp" title="Insert current date and time">Date stamp</button><button type="button" data-command="bold" title="Bold"><b>B</b></button><button type="button" data-command="italic" title="Italic"><i>I</i></button><button type="button" data-command="underline" title="Underline"><u>U</u></button><button type="button" data-command="insertUnorderedList" title="Bulleted list">• List</button><button type="button" data-command="insertOrderedList" title="Numbered list">1. List</button><button type="button" data-command="formatBlock" data-value="h2">Heading</button><button type="button" data-command="formatBlock" data-value="p">Paragraph</button><button type="button" data-command="removeFormat">Clear format</button><button type="button" data-command="undo" title="Undo">↶</button><button type="button" data-command="redo" title="Redo">↷</button></div><div id="notes-editor" contenteditable="true" role="textbox" aria-multiline="true" aria-label="Rich text item notes"></div><div class="notes-footer"><span id="notes-status" role="status" aria-live="polite">Loading…</span><button type="button" id="notes-retry" hidden>Retry save</button></div>';
$('grid-wrap').after(notesPane);
function dismissNotes(){++noteVersion;notesPane.hidden=true;noteItem=null;flush()}
function cleanNotes(html){const source=document.createElement('template');source.innerHTML=html;const allowed=new Set(['P','BR','DIV','B','STRONG','I','EM','U','UL','OL','LI','H2','H3','BLOCKQUOTE']);function copy(node){if(node.nodeType===3)return document.createTextNode(node.textContent);const out=document.createDocumentFragment();if(node.nodeType!==1)return out;if(['SCRIPT','STYLE','IFRAME','OBJECT','SVG','MATH'].includes(node.tagName))return out;const target=allowed.has(node.tagName)?document.createElement(node.tagName.toLowerCase()):out;for(const child of node.childNodes)target.append(copy(child));return target}const holder=document.createElement('div');for(const child of source.content.childNodes)holder.append(copy(child));return holder.innerHTML}
function noteStatus(message,error=false){$('notes-status').textContent=message;$('notes-status').classList.toggle('error',error);$('notes-retry').hidden=!error}
async function openNotes(){const id=$('items').value;if(!id)return;++loadVersion;$('grid-wrap').hidden=true;$('empty').hidden=true;const version=++noteVersion;noteItem=id;$('title').textContent=items.find(item=>item.id===id)?.name||'Item notes';$('description').textContent='Rich text notes · Changes save automatically';$('notes-title').textContent=items.find(item=>item.id===id)?.name+' — Notes';$('notes-editor').innerHTML='';$('notes-editor').contentEditable='false';noteStatus('Loading…');notesPane.hidden=false;try{const rows=await api('pm01_item_notes?item_id=eq.'+id);if(version!==noteVersion||notesPane.hidden)return;$('notes-editor').innerHTML=cleanNotes(notesPending.get(id)?.content_html??rows[0]?.content_html??'');$('notes-editor').contentEditable='true';noteStatus(notesPending.has(id)?'Unsaved changes…':'All changes saved');$('notes-editor').focus()}catch(error){noteStatus('Load failed: '+error.message,true)}}
function queueNote(){if(!noteItem)return;notesPending.set(noteItem,{item_id:noteItem,content_html:cleanNotes($('notes-editor').innerHTML)});noteStatus('Unsaved changes…');status('Unsaved changes…');clearTimeout(saveTimer);saveTimer=setTimeout(flush,500)}
async function saveNotes(){const batch=[...notesPending.entries()];if(!batch.length)return;noteStatus('Saving…');await api('pm01_item_notes?on_conflict=item_id','POST',batch.map(([,entry])=>entry));for(const [id,entry]of batch)if(notesPending.get(id)===entry)notesPending.delete(id);noteStatus(notesPending.size?'Unsaved changes…':'All changes saved')}
$('notes-editor').addEventListener('input',queueNote);$('notes-editor').addEventListener('blur',flush);
$('notes-toolbar').addEventListener('mousedown',event=>{if(event.target.closest('button'))event.preventDefault()});
$('notes-toolbar').addEventListener('click',event=>{const button=event.target.closest('button');if(!button||$('notes-editor').contentEditable!=='true')return;$('notes-editor').focus();if(button.dataset.command==='dateStamp')document.execCommand('insertText',false,dateStamp());else document.execCommand(button.dataset.command,false,button.dataset.value||null);queueNote()});
$('notes-close').textContent='Daily grid';$('notes-close').setAttribute('aria-label','Show daily grid');$('notes-close').onclick=choose;
$('notes-retry').onclick=()=>notesPending.size?flush():openNotes();$('items').addEventListener('dblclick',openNotes);
$('items').addEventListener('keydown',event=>{if(event.key==='Enter'){event.preventDefault();openNotes()}});


const DAYFLOW_URL='https://ynfjfanvdvpyycoeweca.supabase.co';
const DAYFLOW_KEY='sb_publishable_j7q6Ox0GVsUv68D3oQiOBA_2Avx50il';
let importing=false;
function dateStamp(now=new Date()){const parts=new Intl.DateTimeFormat('en-US',{timeZone:'America/Los_Angeles',month:'2-digit',day:'2-digit',weekday:'short',hour:'numeric',minute:'2-digit',hour12:true}).formatToParts(now);const get=type=>parts.find(p=>p.type===type).value;return `${get('month')}-${get('day')} ${get('weekday')}. ${get('hour')}:${get('minute')} ${get('dayPeriod').toLowerCase()}`}
function taskTime(time){const [hour,minute]=time.split(':');return `${Number(hour)%12||12}:${minute} ${Number(hour)<12?'am':'pm'}`}
function groupDayflow(tasks){const dates=new Map();for(const task of tasks){if(!task.date||task.date<'2026-10-01'||task.date>'2027-06-30')continue;if(!dates.has(task.date))dates.set(task.date,[]);dates.get(task.date).push(task)}return new Map([...dates].map(([date,rows])=>[date,rows.sort((a,b)=>(a.start_time||'99:99').localeCompare(b.start_time||'99:99')||a.title.localeCompare(b.title)||a.id.localeCompare(b.id)).map(task=>task.title+(task.start_time?' — '+taskTime(task.start_time):'')).join('\n')]))}
async function dayflowTasks(){const tasks=[];for(let offset=0;;offset+=1000){const response=await fetch(DAYFLOW_URL+'/rest/v1/pm01_dayflow_calendar_export?select=id,title,date,start_time&order=date.asc,id.asc&limit=1000&offset='+offset,{headers:{apikey:DAYFLOW_KEY}});if(!response.ok)throw new Error('Could not read DayFlow items');const page=await response.json();tasks.push(...page);if(page.length<1000)return tasks}}
function showDayflow(entries){dismissNotes();++loadVersion;selected=null;renderItems();$('empty').hidden=true;$('title').textContent='DayFlow';$('description').textContent='DayFlow calendar · Timed items first, then untimed items';buildGrid(entries,true);$('grid-wrap').hidden=false;scrollToToday()}
async function importDayflow(){if(importing)return;await flush();if(saving||pending.size||notesPending.size){status('Wait for changes to save, then click Import DayFlow again.',true);return}importing=true;$('import-dayflow').disabled=true;const version=++loadVersion;try{status('Importing DayFlow…');const tasks=await dayflowTasks();const grouped=groupDayflow(tasks);const cached=await api('pm01_dayflow_entries?select=entry_date');const dates=new Set([...grouped.keys(),...cached.map(row=>row.entry_date)]);const updates=[...dates].map(entry_date=>({entry_date,content:grouped.get(entry_date)||''}));if(updates.length)await api('pm01_dayflow_entries?on_conflict=entry_date','POST',updates);if(version===loadVersion){showDayflow(updates);status(`Imported ${tasks.length} DayFlow items · All changes saved`)}}catch(error){status(error.message+' · Click Import DayFlow to retry',true)}finally{importing=false;$('import-dayflow').disabled=false}}
$('import-dayflow').onclick=importDayflow;

refresh();
